const SpeedVisual: React.FC<{ activeFrame: number; active: boolean }> = ({ activeFrame, active }) => {
  // Speed needle math sweep (reconstruction effect)
  let currentSpeed = 0;
  if (active) {
    if (activeFrame < 35) {
      currentSpeed = interpolate(activeFrame, [0, 35], [0, 112], {
        extrapolateRight: "clamp",
        easing: Easing.out(Easing.quad),
      });
    } else if (activeFrame < 70) {
      currentSpeed = interpolate(activeFrame, [35, 70], [112, 68], {
        extrapolateRight: "clamp",
        easing: Easing.out(Easing.cubic),
      });
    } else {
      currentSpeed = 68 + Math.sin(activeFrame * 0.08) * 0.3;
    }
  }

  const angleStart = -210;
  const angleEnd = 30;
  const targetAngle = angleStart + (currentSpeed / 160) * (angleEnd - angleStart);

  // Speedometer ticks
  const ticks = [];
  for (let i = 0; i <= 160; i += 10) {
    const angle = angleStart + (i / 160) * (angleEnd - angleStart);
    const rad = (angle * Math.PI) / 180;
    const isMajor = i % 20 === 0;
    const rOuter = 75;
    const rInner = isMajor ? 65 : 71;
    
    const x1 = 100 + rOuter * Math.cos(rad);
    const y1 = 100 + rOuter * Math.sin(rad);
    const x2 = 100 + rInner * Math.cos(rad);
    const y2 = 100 + rInner * Math.sin(rad);

    ticks.push(
      <line
        key={i}
        x1={x1}
        y1={y1}
        x2={x2}
        y2={y2}
        stroke={i <= currentSpeed ? "#e5a93c" : "rgba(255,255,255,0.18)"}
        strokeWidth={isMajor ? 1.8 : 0.8}
      />
    );
  }

  return (
    <div style={{ width: "100%", height: "100%", position: "relative", display: "flex", justifyContent: "center", alignItems: "center" }}>
      <svg width="90%" height="90%" viewBox="0 0 200 200" style={{ overflow: "visible" }}>
        {/* Speedometer ring */}
        <circle cx="100" cy="100" r="80" fill="none" stroke="rgba(229, 169, 60, 0.08)" strokeWidth="6" />
        <circle cx="100" cy="100" r="80" fill="none" stroke="#e5a93c" strokeWidth="1.2" strokeDasharray="6 4" opacity="0.3" />
        
        {ticks}

        {/* Dial values */}
        <text x="50" y="152" fill="rgba(255,255,255,0.5)" fontSize="8" textAnchor="middle" fontFamily="sans-serif">0</text>
        <text x="35" y="112" fill="rgba(255,255,255,0.5)" fontSize="8" textAnchor="middle" fontFamily="sans-serif">20</text>
        <text x="48" y="74" fill="rgba(255,255,255,0.5)" fontSize="8" textAnchor="middle" fontFamily="sans-serif">40</text>
        <text x="78" y="52" fill="rgba(255,255,255,0.5)" fontSize="8" textAnchor="middle" fontFamily="sans-serif">60</text>
        <text x="118" y="52" fill="rgba(255,255,255,0.5)" fontSize="8" textAnchor="middle" fontFamily="sans-serif">80</text>
        <text x="152" y="74" fill="rgba(255,255,255,0.5)" fontSize="8" textAnchor="middle" fontFamily="sans-serif">100</text>
        <text x="165" y="112" fill="rgba(255,255,255,0.5)" fontSize="8" textAnchor="middle" fontFamily="sans-serif">120</text>
        <text x="150" y="152" fill="rgba(255,255,255,0.5)" fontSize="8" textAnchor="middle" fontFamily="sans-serif">140</text>

        {/* Digital numbers */}
        <text x="100" y="115" fill="#ffffff" fontSize="22" fontWeight="bold" textAnchor="middle" fontFamily="sans-serif" style={{ filter: "drop-shadow(0 0 3px rgba(255,255,255,0.3))" }}>
          {Math.round(currentSpeed)}
        </text>
        <text x="100" y="130" fill="#e5a93c" fontSize="9" fontWeight="600" letterSpacing="1" textAnchor="middle" fontFamily="sans-serif">
          MPH
        </text>

        {/* Pointer Needle */}
        {active && (
          <g transform={`rotate(${targetAngle + 90}, 100, 100)`}>
            <path d="M 97,100 L 100,30 L 103,100 Z" fill="#e5a93c" style={{ filter: "drop-shadow(0 0 4px rgba(229,169,60,0.8))" }} />
            <circle cx="100" cy="100" r="5" fill="#0d1527" stroke="#e5a93c" strokeWidth="2" />
          </g>
        )}
      </svg>
    </div>
  );
};

const WitnessVisual: React.FC<{ activeFrame: number; active: boolean }> = ({ activeFrame, active }) => {
  const totalBars = 32;
  const bars = [];
  for (let i = 0; i < totalBars; i++) {
    let waveHeight = 2;
    if (active) {
      const distanceFromCenter = Math.abs(i - totalBars / 2) / (totalBars / 2);
      const envelope = Math.max(0, 1 - distanceFromCenter);
      const freq1 = activeFrame * 0.18 + i * 0.45;
      const freq2 = activeFrame * 0.09 - i * 0.25;
      waveHeight = Math.abs(Math.sin(freq1) * 16 + Math.cos(freq2) * 8) * envelope + 2;
    }
    bars.push(waveHeight);
  }

  return (
    <div style={{ width: "100%", height: "100%", position: "relative", display: "flex", justifyContent: "center", alignItems: "center" }}>
      <svg width="95%" height="95%" viewBox="0 0 200 200" style={{ overflow: "visible" }}>
        {/* Person Head Profile Outline */}
        <path
          d="M 15,160 C 15,140 25,120 28,110 C 25,100 25,85 28,65 C 32,45 48,40 58,45 C 68,50 68,65 65,80 C 68,82 72,85 72,90 C 72,95 67,97 66,99 C 64,103 62,108 58,112 C 55,115 52,125 55,145 C 57,155 58,160 58,160 Z"
          fill="none"
          stroke="rgba(255, 255, 255, 0.4)"
          strokeWidth="1.5"
          strokeLinecap="round"
        />

        {/* Statement dialogue box */}
        <g transform="translate(85, 45)">
          <rect x="0" y="0" width="100" height="50" rx="6" fill="#0d1527" stroke="rgba(229,169,60,0.3)" strokeWidth="1" />
          <path d="M 0,20 L -12,25 L 0,30 Z" fill="#0d1527" stroke="rgba(229,169,60,0.3)" strokeWidth="1" />
          <path d="M 0,21 L 0,29" stroke="#0d1527" strokeWidth="2.5" />

          {/* Lines representing written statement */}
          <line x1="12" y1="15" x2="88" y2="15" stroke="rgba(255,255,255,0.5)" strokeWidth="2.5" strokeLinecap="round" />
          <line x1="12" y1="25" x2="75" y2="25" stroke="rgba(255,255,255,0.5)" strokeWidth="2.5" strokeLinecap="round" />
          <line x1="12" y1="35" x2="55" y2="35" stroke="rgba(255,255,255,0.5)" strokeWidth="2.5" strokeLinecap="round" />
        </g>

        {/* Voice Oscilloscope Waveform */}
        <g transform="translate(20, 135)">
          <line x1="0" y1="20" x2="160" y2="20" stroke="rgba(229,169,60,0.15)" strokeWidth="1" />
          {bars.map((h, idx) => {
            const x = (idx / totalBars) * 160;
            return (
              <line
                key={idx}
                x1={x}
                y1={20 - h / 2}
                x2={x}
                y2={20 + h / 2}
                stroke="#e5a93c"
                strokeWidth="2.5"
                strokeLinecap="round"
                opacity={active ? 0.95 : 0.3}
                style={{ filter: "drop-shadow(0 0 2px rgba(229,169,60,0.5))" }}
              />
            );
          })}
        </g>
      </svg>
    </div>
  );
};

