export type CaseEvidenceProps = Record<string, any>;

const CaseEvidence: React.FC<CaseEvidenceProps> = ({
  backgroundColor = "#060b13",
  transparentBackground = false,
  durationInSeconds = 15,
  mainTitle = "EVIDENCE ANALYSIS",
  mainSubtitle = "INCIDENT RECONSTRUCTION SYSTEM",
  crosswalkTitle = "CROSSWALK",
  crosswalkDesc = "Identifies pedestrian activity and right of way.",
  lightTitle = "LIGHT",
  lightDesc = "Confirms signal timing and light conditions at the time.",
  speedTitle = "DRIVER'S SPEED",
  speedDesc = "Captures vehicle speed to assess impact and response.",
  witnessTitle = "WITNESS STATEMENTS",
  witnessDesc = "Collects and verifies independent accounts of the incident.",
  videoTitle = "VIDEO EVIDENCE",
  videoDesc = "Provides visual evidence to reconstruct events as they happened.",
  reportTitle = "POLICE REPORT",
  reportDesc = "Official documentation of findings, citations, and observations.",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Resolve background color
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Header Animation spring
  const headerSpring = spring({
    frame,
    fps,
    config: { damping: 14, mass: 0.8 },
  });

  const headerY = interpolate(headerSpring, [0, 1], [-60, 0]);
  const headerOpacity = interpolate(headerSpring, [0, 1], [0, 1]);

  // Combined dataset for map-rendering the panels
  const evidenceItems = [
    {
      title: crosswalkTitle,
      desc: crosswalkDesc,
      visual: (af: number, act: boolean) => <CrosswalkVisual activeFrame={af} active={act} />,
      badge: <PedestrianBadge />,
    },
    {
      title: lightTitle,
      desc: lightDesc,
      visual: (af: number, act: boolean) => <LightVisual activeFrame={af} active={act} />,
      badge: <LightBadge />,
    },
    {
      title: speedTitle,
      desc: speedDesc,
      visual: (af: number, act: boolean) => <SpeedVisual activeFrame={af} active={act} />,
      badge: <SpeedBadge />,
    },
    {
      title: witnessTitle,
      desc: witnessDesc,
      visual: (af: number, act: boolean) => <WitnessVisual activeFrame={af} active={act} />,
      badge: <WitnessBadge />,
    },
    {
      title: videoTitle,
      desc: videoDesc,
      visual: (af: number, act: boolean) => <VideoVisual activeFrame={af} active={act} />,
      badge: <VideoBadge />,
    },
    {
      title: reportTitle,
      desc: reportDesc,
      visual: (af: number, act: boolean) => <ReportVisual activeFrame={af} active={act} />,
      badge: <ReportBadge />,
    },
  ];

  // Precise calculated dimensions
  const headerHeight = height * 0.11;
  const contentHeight = height * 0.79;
  const footerHeight = height * 0.10;
  const rowHeight = contentHeight / 6;

  // Responsive font sizes
  const titleFontSize = Math.max(15, width * 0.038);
  const descFontSize = Math.max(11, width * 0.026);
  const mainTitleSize = Math.max(22, width * 0.048);
  const subTitleSize = Math.max(11, width * 0.025);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, color: "#ffffff", overflow: "hidden" }}>
      {/* Background blueprint tech pattern */}
      <svg style={{ position: "absolute", width: "100%", height: "100%", opacity: 0.12, pointerEvents: "none" }}>
        <defs>
          <pattern id="grid" width="40" height="40" patternUnits="userSpaceOnUse">
            <path d="M 40 0 L 0 0 0 40" fill="none" stroke="#e5a93c" strokeWidth="0.5" />
          </pattern>
        </defs>
        <rect width="100%" height="100%" fill="url(#grid)" />
      </svg>

      {/* 1. Header Area */}
      <div
        style={{
          height: headerHeight,
          width: "100%",
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          paddingLeft: "6%",
          paddingRight: "6%",
          borderBottom: "1px solid rgba(229,169,60,0.25)",
          boxSizing: "border-box",
          transform: `translateY(${headerY}px)`,
          opacity: headerOpacity,
          zIndex: 10,
          backgroundColor: "#060b13",
          transition: "none",
        }}
      >
        <div
          style={{
            fontFamily: spaceGroteskFamily,
            fontSize: mainTitleSize,
            fontWeight: "bold",
            color: "#e5a93c",
            letterSpacing: "2px",
            lineHeight: 1.2,
          }}
        >
          {mainTitle}
        </div>
        <div
          style={{
            fontFamily: interFamily,
            fontSize: subTitleSize,
            color: "rgba(255,255,255,0.6)",
            letterSpacing: "1px",
            marginTop: "3px",
          }}
        >
          {mainSubtitle}
        </div>
      </div>

      {/* 2. Content Stack (The 6 Rows) */}
      <div
        style={{
          height: contentHeight,
          width: "100%",
          display: "flex",
          flexDirection: "column",
          boxSizing: "border-box",
          zIndex: 5,
        }}
      >
        {evidenceItems.map((item, idx) => {
          // Row level staggered animations (each starts 12 frames after previous)
          const startFrame = idx * 12;
          const rowSpring = spring({
            frame: frame - startFrame,
            fps,
            config: { damping: 14, mass: 0.8 },
          });

          const rowY = interpolate(rowSpring, [0, 1], [60, 0]);
          const rowOpacity = interpolate(rowSpring, [0, 1], [0, 1]);

          const rowActive = frame >= startFrame;
          const rowActiveFrame = Math.max(0, frame - startFrame);

          return (
            <div
              key={idx}
              style={{
                display: "flex",
                flexDirection: "row",
                height: rowHeight,
                width: "100%",
                borderBottom: "1px solid rgba(229, 169, 60, 0.12)",
                boxSizing: "border-box",
                transform: `translateY(${rowY}px)`,
                opacity: rowOpacity,
                backgroundColor: "rgba(6, 11, 19, 0.4)",
                transition: "none",
              }}
            >
              {/* Left Panel: Animated Graphic Area (40% width) */}
              <div
                style={{
                  width: "40%",
                  height: "100%",
                  borderRight: "1px solid rgba(229, 169, 60, 0.12)",
                  boxSizing: "border-box",
                  display: "flex",
                  justifyContent: "center",
                  alignItems: "center",
                  position: "relative",
                  overflow: "hidden",
                }}
              >
                {item.visual(rowActiveFrame, rowActive)}
              </div>

              {/* Right Panel: Informational Content Area (60% width) */}
              <div
                style={{
                  width: "60%",
                  height: "100%",
                  display: "flex",
                  flexDirection: "column",
                  justifyContent: "center",
                  paddingLeft: "5%",
                  paddingRight: "5%",
                  boxSizing: "border-box",
                }}
              >
                {/* Title and accent bar */}
                <div style={{ display: "flex", flexDirection: "column", marginBottom: 6 }}>
                  <div
                    style={{
                      fontFamily: spaceGroteskFamily,
                      fontSize: titleFontSize,
                      fontWeight: "700",
                      color: "#e5a93c",
                      letterSpacing: "1px",
                      textTransform: "uppercase",
                    }}
                  >
                    {item.title}
                  </div>
                  <div
                    style={{
                      width: "25px",
                      height: "2.5px",
                      backgroundColor: "#e5a93c",
                      marginTop: "4px",
                    }}
                  />
                </div>

                {/* Badge and description details block */}
                <div style={{ display: "flex", flexDirection: "row", alignItems: "flex-start", marginTop: "2px" }}>
                  <div
                    style={{
                      width: "36px",
                      height: "36px",
                      borderRadius: "50%",
                      border: "1px solid rgba(229, 169, 60, 0.45)",
                      display: "flex",
                      justifyContent: "center",
                      alignItems: "center",
                      backgroundColor: "rgba(229,169,60,0.06)",
                      marginRight: "12px",
                      boxSizing: "border-box",
                      flexShrink: 0,
                    }}
                  >
                    {item.badge}
                  </div>
                  <div
                    style={{
                      fontFamily: interFamily,
                      fontSize: descFontSize,
                      color: "rgba(255, 255, 255, 0.75)",
                      lineHeight: "1.35",
                      flex: 1,
                    }}
                  >
                    {item.desc}
                  </div>
                </div>
              </div>
            </div>
          );
        })}
      </div>

      {/* 3. Footer Area */}
      <div
        style={{
          height: footerHeight,
          width: "100%",
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          paddingLeft: "6%",
          paddingRight: "6%",
          boxSizing: "border-box",
          backgroundColor: "#060b13",
          borderTop: "1px solid rgba(229, 169, 60, 0.15)",
          zIndex: 10,
        }}
      >
        <div
          style={{
            fontFamily: interFamily,
            fontSize: Math.max(9, width * 0.022),
            color: "rgba(255, 255, 255, 0.4)",
            letterSpacing: "1px",
          }}
        >
          MALLOY STUDIO DIGITAL FORENSICS
        </div>
        <div
          style={{
            fontFamily: spaceGroteskFamily,
            fontSize: Math.max(9, width * 0.022),
            color: "#e5a93c",
            fontWeight: "bold",
            letterSpacing: "1px",
          }}
        >
          SECURE EVIDENCE ARCHIVE // PART-1
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default CaseEvidence;